<script setup>
import { watch, ref, onMounted } from 'vue';
import { storeToRefs } from "pinia";
import { CircleCloseFilled, InfoFilled } from '@element-plus/icons-vue';
import { axiosPost } from '../../../Axios/post';
import { SuccessFilled, Download  } from '@element-plus/icons-vue';
const postId = ref('');
const fileType = ref('csv');
const open = ref(false);
const loading = ref(false);
const completed = ref(false);
const exportReason = ref('');
const inpurData = ref('');
const fileName = ref('');
const filePath = ref('');
const percentage = ref(0);

const { settings_saved: settingsSaved } = window.fvGlobalVar;
const isExportReason = settingsSaved?.csv_export_reason;

onMounted(() => {
    
    const exportBtns = document.querySelectorAll('#fv-export-data-btn');
    exportBtns.forEach((profile) => {
			profile.addEventListener('click', (e) => {
				e.preventDefault();
                postId.value = profile.getAttribute('data-postId');
                fileType.value = profile.getAttribute('data-fileType') || 'csv';
                open.value = !open.value;
			});
		});
});

// FIXED: Recursive export function that processes data in batches
// - Resets fileName/filePath only on first iteration (offset=0) to allow appending
// - Maintains loading state throughout the process
// - Recursively calls itself until all records are processed
const exportData = async ({ offset = 0, total: t = '', currentPage = 1 }) => {
    // IMPORTANT: Only reset on first iteration to prevent file overwrites
    // On subsequent iterations, fileName and filePath must be preserved
    // so the backend can append to the existing CSV file
    if (offset === 0) {
        fileName.value = '';
        filePath.value = '';
        loading.value = true;
        completed.value = false;
        percentage.value = 0;
    }

    const { data } = await axiosPost({
        queryParams: {
            post_id: postId.value,
            fileName: fileName.value,
            offset,
            total: t,
            csv_reason: exportReason.value,
            current_page: currentPage,
        },
        action: 'fv_export_data',
    });
    const {
        error,
        filename,
        path,
        post_id: pid,
        processed,
        total,
        page,
    } = data;
    
    // FIXED: Always update filename from response for subsequent batches
    // The backend returns the filename so it can be passed to the next iteration
    if (filename) {
        fileName.value = filename;
    }
    
    // FIXED: Only update filePath when export is complete (path is returned)
    // Backend only sends the download path on the final batch
    if (path) {
        filePath.value = path;
    }
    
    // Calculate and update progress percentage
    if (total === 0) {
        percentage.value = 100;
    } else {
        percentage.value = Math.round((100 / total) * processed);
    }

    // FIXED: Mark as completed only when path is available (final batch)
    // This ensures the download link appears only after all data is exported
    if (path !== '') {
        loading.value = false;
        completed.value = true;
    }

    // FIXED: Recursive call with await to ensure batches process sequentially
    // Passes the updated offset, total count, and next page number
    if (processed < total) {
        await exportData({
            offset: processed,
            total,
            currentPage: page,
        });
    }
}

// REMOVED: startExport function is no longer needed
// exportData now handles everything recursively

watch([fileName],() => {
    if(fileName){
        setExportPostMeta();
    }
})
const setExportPostMeta = async () => {
    const { data } = await axiosPost({
        queryParams: {
            filename: fileName.value,
            post_id: postId.value,
            filepath: filePath.value,
        },
        action: 'fv_set_export_meta_data',
    });
};
</script>
<template>
    <el-config-provider>
        <div v-if="open">
            <el-dialog v-model="open" title="Export Data" align-center="true" width="600px">
                <template #header="{ close, titleId, titleClass }">
                    <div class="fv-header-title">
                        <el-icon size="20">
                            <InfoFilled />
                        </el-icon>
                        <strong>Export Data Content</strong>
                    </div>
                </template>
                <div v-if="!loading && !completed" class="fv-export-dialog-content">
                    <p class="fv-export-dailog-heading">
                        Please do not close the window while export is in progress!
                    </p>
                    <el-input v-model="exportReason" type="textarea" row="4" placeholder="Export Reason" v-if="isExportReason" />
                    <span class="fv-export-file">{{ postId }}.{{ fileType }}{{ exportReason }}</span>
                    <div>
                        <el-button type="primary" @click="() => exportData({ offset: 0 })">Start Export</el-button>
                    </div>
                </div>
                <div v-else class="fv-export-action-dialog">
                    <div v-if="completed">
                        <span class="fv-export-status">Completed</span>
                    </div>
                    <div v-if="!completed" class="fv-export-per">
                        Percentage :  {{ percentage }}
                    </div>
                    <div v-else>
                        <el-icon><SuccessFilled /></el-icon>
                    </div>
                </div>
                
                <div v-if="completed" class="fv-export-download">
                    <el-link :href = "filePath" :icon="Download" :download = "fileName+'.csv'">Download</el-link>
                </div>
                
            </el-dialog>
        </div>
    </el-config-provider>
</template>